import csv
from collections import defaultdict
from datetime import date

with open('/home/agent/workspace/bookstore_orders.csv', newline='') as f:
    rows = list(csv.DictReader(f))

def to_date(s):
    return date.fromisoformat(s.strip().split(' ')[0])

stats = defaultdict(lambda: [0, 0])
for r in rows:
    if r['fulfillment_status'] != 'Delivered':
        continue
    c = r['carrier_name'].strip()
    stats[c][0] += 1
    if to_date(r['actual_delivery_date']) <= to_date(r['estimated_delivery_date']):
        stats[c][1] += 1

results = [
    (c, tot, ontime, round(ontime / tot * 100, 2))
    for c, (tot, ontime) in stats.items()
]
results.sort(key=lambda t: -t[3])

with open('/home/agent/workspace/carrier-otd.csv', 'w', newline='') as f:
    w = csv.writer(f)
    w.writerow(['CarrierName', 'TotalDelivered', 'OnTimeDelivered', 'OnTimePct'])
    w.writerows(results)

for row in results:
    print(row)

